// lib/python/errors.mjs
//
// Python-flavoured exception objects.  Each carries the Python-side call frames
// that CPython would have shown in a traceback, so that stderr can be rendered
// with the same shape as the reference program.

/** Base class for the emulated Python exceptions. */
export class PythonError extends Error {
  /**
   * @param {string} typeName  e.g. "ValueError"
   * @param {string} text      the message printed after "TypeName: "
   */
  constructor(typeName, text) {
    super(`${typeName}: ${text}`);
    this.typeName = typeName;
    this.text = text;
    /** @type {Array<{file: string, line: number, name: string}>} */
    this.pyFrames = [];
  }

  /** Push a frame that is "deeper" than the ones already recorded. */
  pushFrame(frame) {
    this.pyFrames.push(frame);
    return this;
  }

  /** Prepend a frame that is "shallower" than the ones already recorded. */
  unshiftFrame(frame) {
    this.pyFrames.unshift(frame);
    return this;
  }
}

export class PyValueError extends PythonError {
  constructor(text) {
    super('ValueError', text);
  }
}

export class PyUnicodeEncodeError extends PythonError {
  constructor(text) {
    super('UnicodeEncodeError', text);
  }
}

/** Mirror of Python's SystemExit, raised by the argument parser. */
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.code = code;
  }
}

