// lib/python/repr.mjs
//
// Reproduces CPython's `repr()` for `bytes` objects (what `print(b'...')`
// emits) and for one-character `str` objects (used by the base58 library's
// "Invalid character {!r}" message).

const QUOTE_SINGLE = 0x27; // '
const QUOTE_DOUBLE = 0x22; // "
const BACKSLASH = 0x5c; // \
const TAB = 0x09;
const NEWLINE = 0x0a;
const RETURN = 0x0d;

function hex2(value) {
  const out = value.toString(16);
  return out.length < 2 ? `0${out}` : out;
}

/**
 * Pick the delimiter the way CPython does: a single quote unless the payload
 * contains a single quote but no double quote.
 */
function chooseQuote(values) {
  const hasSingle = values.includes(QUOTE_SINGLE);
  const hasDouble = values.includes(QUOTE_DOUBLE);
  return hasSingle && !hasDouble ? QUOTE_DOUBLE : QUOTE_SINGLE;
}

/** Escape one byte for display inside a bytes/str literal. */
function escapeByte(value, quote) {
  if (value === BACKSLASH) return '\\\\';
  if (value === quote) return `\\${String.fromCharCode(quote)}`;
  if (value === TAB) return '\\t';
  if (value === NEWLINE) return '\\n';
  if (value === RETURN) return '\\r';
  if (value < 0x20 || value >= 0x7f) return `\\x${hex2(value)}`;
  return String.fromCharCode(value);
}

/**
 * `repr(bytes_object)` — e.g. [0x39, 0xff] -> `b'9\xff'`.
 *
 * @param {number[]} bytes
 * @returns {string}
 */
export function bytesRepr(bytes) {
  const quote = chooseQuote(bytes);
  const delim = String.fromCharCode(quote);
  let body = '';
  for (const value of bytes) body += escapeByte(value, quote);
  return `b${delim}${body}${delim}`;
}

/**
 * `repr(chr(byte))` for a byte in 0..127 — e.g. 0x27 -> `"'"`, 0x5c -> `'\\'`.
 * Only ASCII is needed: the base58 decoder rejects non-ASCII input earlier,
 * before any byte can reach the "Invalid character" path.
 *
 * @param {number} byteValue
 * @returns {string}
 */
export function asciiCharRepr(byteValue) {
  const quote = chooseQuote([byteValue]);
  const delim = String.fromCharCode(quote);
  return `${delim}${escapeByte(byteValue, quote)}${delim}`;
}

