// lib/numeric/bigint.mjs
//
// Conversions between big-endian byte arrays and arbitrary-precision integers.
// Routed through hexadecimal so that a long payload costs one pass instead of
// one big-integer multiply per byte.

const HEX_DIGITS = '0123456789abcdef';

/** `int.from_bytes(bytes, 'big')`. */
export function bytesToInt(bytes) {
  if (bytes.length === 0) return 0n;
  let hex = '';
  for (const value of bytes) {
    hex += HEX_DIGITS[(value >> 4) & 0xf];
    hex += HEX_DIGITS[value & 0xf];
  }
  return BigInt(`0x${hex}`);
}

/**
 * Shortest big-endian byte array holding `value` (0 becomes an empty array,
 * matching the base58 library's shift-and-collect loop).
 */
export function intToBytes(value) {
  if (value <= 0n) return [];
  let hex = value.toString(16);
  if (hex.length % 2 === 1) hex = `0${hex}`;
  const bytes = [];
  for (let i = 0; i < hex.length; i += 2) {
    bytes.push(parseInt(hex.slice(i, i + 2), 16));
  }
  return bytes;
}

