// lib/python/linecache.mjs
//
// The slice of CPython's `linecache` a traceback needs: fetch one line of a
// source file by number, resolving relative paths against the process's current
// directory.
//
// The reference program behaves the same way — its traceback shows the offending
// source line only when a readable `test15.py` happens to sit in the cwd, and it
// shows whatever that file's line N contains, even if unrelated to the code that
// actually ran.

import { readFileSync } from 'node:fs';

/** filename -> lines, mirroring linecache's module-level cache. */
const cache = new Map();

function loadLines(fileName) {
  if (cache.has(fileName)) return cache.get(fileName);
  let lines = null;
  try {
    const text = readFileSync(fileName, 'utf8');
    // Universal newlines, keeping the line terminator like readlines() does.
    lines = text.split(/(?<=\n)/).map((line) => line.replace(/\r\n$/, '\n'));
  } catch {
    lines = null;
  }
  cache.set(fileName, lines);
  return lines;
}

/**
 * `linecache.getline(filename, lineno)` — the raw line including its trailing
 * newline, or '' when unavailable.
 *
 * @param {string} fileName
 * @param {number} lineNumber 1-based
 * @returns {string}
 */
export function getLine(fileName, lineNumber) {
  const lines = loadLines(fileName);
  if (lines === null) return '';
  if (lineNumber < 1 || lineNumber > lines.length) return '';
  return lines[lineNumber - 1];
}

