  const rawLine = getLine(frame.file, frame.line);
  const stripped = stripBoth(rawLine);
  if (stripped.length === 0) return [];

  const rows = [`${SOURCE_INDENT}${stripped}`];
  if (frame.colno === undefined || frame.endColno === undefined) return rows;

  const startOffset = byteOffsetToCharOffset(rawLine, frame.colno) + 1;
  const endOffset = byteOffsetToCharOffset(rawLine, frame.endColno) + 1;
  const strippedCharacters = charLength(rawLine) - charLength(stripped);
  const caretCount = endOffset - startOffset;

  // Carets are suppressed when the expression spans the whole visible line.
  if (caretCount <= 0 || caretCount >= charLength(stripped)) return rows;

  const indent = Math.max(0, startOffset - strippedCharacters);
  rows.push(`${SOURCE_INDENT}${' '.repeat(indent)}${'^'.repeat(caretCount)}`);
  return rows;
}

/**
 * @param {PythonError} error
 * @param {ScriptFrame} scriptFrame
 * @returns {string} the traceback, newline-terminated
 */
export function formatTraceback(error, scriptFrame) {
  const lines = ['Traceback (most recent call last):'];
  lines.push(
    `  File "${scriptFrame.file}", line ${scriptFrame.line}, in ${scriptFrame.name}`,
  );
  lines.push(...formatSourceLines(scriptFrame));

  for (const frame of error instanceof PythonError ? error.pyFrames : []) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
  }

  lines.push(`${error.typeName}: ${error.text}`);
  return `${lines.join('\n')}\n`;
}

/**
 * The line the PyInstaller bootloader prints after an unhandled exception.  Its
 * numeric field is the process id, so it differs between runs of the reference
 * program too.
 */
export function formatFrozenFooter(scriptName, pid) {
  return `[PYI-${pid}:ERROR] Failed to execute script '${scriptName}' `
    + 'due to unhandled exception!\n';
}

/** Write the traceback plus footer to stderr. */
export function reportFatal(error, scriptFrame, scriptName, pid) {
  process.stderr.write(formatTraceback(error, scriptFrame));
  process.stderr.write(formatFrozenFooter(scriptName, pid));
}

