// lib/python/traceback.mjs
//
// Renders an uncaught PythonError the way the reference program does: a CPython
// traceback followed by the frozen-app footer.
//
// Only the top (script) frame shows a source line, because the bundled library
// modules have no source available at run time — matching the reference output.

import { PythonError } from './errors.mjs';

const SOURCE_INDENT = '    ';

/**
 * @typedef {object} ScriptFrame
 * @property {string} file    file name shown in the traceback
 * @property {number} line   line number shown in the traceback
 * @property {string} name   function name, e.g. "<module>"
 * @property {string} [source]      the source line, without leading indentation
 * @property {number} [markStart]   column in `source` where the carets begin
 * @property {number} [markLength]  how many carets to draw
 */

/**
 * @param {PythonError} error
 * @param {ScriptFrame} scriptFrame
 * @returns {string} the traceback, newline-terminated
 */
export function formatTraceback(error, scriptFrame) {
  const lines = ['Traceback (most recent call last):'];

  lines.push(
    `  File "${scriptFrame.file}", line ${scriptFrame.line}, in ${scriptFrame.name}`,
  );
  if (scriptFrame.source !== undefined) {
    lines.push(`${SOURCE_INDENT}${scriptFrame.source}`);
    if (scriptFrame.markLength) {
      const pad = ' '.repeat(SOURCE_INDENT.length + (scriptFrame.markStart || 0));
      lines.push(`${pad}${'^'.repeat(scriptFrame.markLength)}`);
    }
  }

  for (const frame of error instanceof PythonError ? error.pyFrames : []) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
  }

  lines.push(`${error.typeName}: ${error.text}`);
  return `${lines.join('\n')}\n`;
}

/**
 * The line the PyInstaller bootloader prints after an unhandled exception.  The
 * numeric field is the process id, so it differs from run to run in the
 * reference program too.
 */
export function formatFrozenFooter(scriptName, pid) {
  return `[PYI-${pid}:ERROR] Failed to execute script '${scriptName}' `
    + 'due to unhandled exception!\n';
}

/** Write the traceback plus footer to stderr. */
export function reportFatal(error, scriptFrame, scriptName, pid) {
  process.stderr.write(formatTraceback(error, scriptFrame));
  process.stderr.write(formatFrozenFooter(scriptName, pid));
}

