import { PythonError } from './errors.mjs';
import { getLine } from './linecache.mjs';
import { encodeUtf8, isPythonSpace, toCodePoints } from './unicode.mjs';

const SOURCE_INDENT = '    ';

/** `str.strip()` / `str.lstrip()` over Python's whitespace set. */
function stripBoth(text) {
  const points = toCodePoints(text);
  let start = 0;
  let end = points.length;
  while (start < end && isPythonSpace(points[start])) start += 1;
  while (end > start && isPythonSpace(points[end - 1])) end -= 1;
  return points.slice(start, end).map((cp) => String.fromCodePoint(cp)).join('');
}

/** Number of code points in a string (not UTF-16 units). */
function charLength(text) {
  return toCodePoints(text).length;
}

/**
 * `traceback._byte_offset_to_character_offset`: how many characters the first
 * `offset + 1` UTF-8 bytes of `text` cover, a partially covered character
 * counting as one (the decoder would substitute one replacement character).
 */
function byteOffsetToCharOffset(text, offset) {
  const limit = offset + 1;
  let bytesSeen = 0;
  let chars = 0;
  for (const codePoint of toCodePoints(text)) {
    if (bytesSeen >= limit) break;
    bytesSeen += encodeUtf8(String.fromCodePoint(codePoint)).length;
    chars += 1;
  }
  return chars;
}

/**
 * @typedef {object} ScriptFrame
 * @property {string} file      file name shown in the traceback and looked up
 * @property {number} line      line number shown in the traceback
 * @property {string} name      function name, e.g. "<module>"
 * @property {number} [colno]     start column of the failing expression
 * @property {number} [endColno]  end column of the failing expression
 */

/** The source line plus caret line for a frame, or [] when unavailable. */
function formatSourceLines(frame) {
  const rawLine = getLine(frame.file, frame.line);
  const stripped = stripBoth(rawLine);
  if (stripped.length === 0) return [];

  const rows = [`${SOURCE_INDENT}${stripped}`];
  if (frame.colno === undefined || frame.endColno === undefined) return rows;

  const startOffset = byteOffsetToCharOffset(rawLine, frame.colno) + 1;
  const endOffset = byteOffsetToCharOffset(rawLine, frame.endColno) + 1;
  const strippedCharacters = charLength(rawLine) - charLength(stripped);
  const caretCount = endOffset - startOffset;

  // Carets are suppressed when the expression spans the whole visible line.
  if (caretCount <= 0 || caretCount >= charLength(stripped)) return rows;

  const indent = Math.max(0, startOffset - strippedCharacters);
  rows.push(`${SOURCE_INDENT}${' '.repeat(indent)}${'^'.repeat(caretCount)}`);
  return rows;
}

