#!/usr/bin/env node
// Probe how the reference renders the traceback source row for various planted
// test15.py line-13 contents.  Prints the exact stderr region for each.

import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const EXE = '/workspace/dataset/test15_executable';
const PORT = '/output/test15.mjs';

const line13Cases = {
  'empty': '',
