#!/usr/bin/env node
// Sweep leading-indent widths and body shapes to derive the reference's exact
// traceback source-row / caret-row rule.

import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const EXE = '/workspace/dataset/test15_executable';

function refRegion(line13) {
  const dir = mkdtempSync(join(tmpdir(), 'sweep-'));
  const lines = [];
  for (let i = 1; i <= 12; i += 1) lines.push(`line${i}`);
  lines.push(line13);
  lines.push('line14');
  writeFileSync(join(dir, 'test15.py'), `${lines.join('\n')}\n`);
  const r = spawnSync(EXE, ['--a', 'X', '--b', 'Y', '--c', '0', '--d', 'z'], {
    cwd: dir, encoding: 'utf8',
  });
  const rows = (r.stderr ?? '').split('\n');
  // rows[0] = "Traceback...", rows[1] = File test15.py, then source/caret rows
  const out = [];
  for (let i = 2; i < rows.length; i += 1) {
    if (rows[i].startsWith('  File ')) break;
    out.push(rows[i]);
  }
  return out;
}

const BODY = 'dec1 = base58.b58decode(args.c)  # tail tail tail';
console.log('--- indent sweep, body = %j (len %d)', BODY, BODY.length);
for (let n = 0; n <= 12; n += 1) {
  const rows = refRegion(' '.repeat(n) + BODY);
  console.log(`indent=${String(n).padStart(2)}  rows=${JSON.stringify(rows)}`);
}

console.log('\n--- indent sweep, body = 40 x');
for (let n = 0; n <= 12; n += 1) {
  const rows = refRegion(' '.repeat(n) + 'x'.repeat(40));
  console.log(`indent=${String(n).padStart(2)}  rows=${JSON.stringify(rows)}`);
}

console.log('\n--- tab indents, body = %j', BODY);
for (let n = 0; n <= 3; n += 1) {
  const rows = refRegion('\t'.repeat(n) + BODY);
  console.log(`tabs=${n}  rows=${JSON.stringify(rows)}`);
}

console.log('\n--- trailing whitespace, body = 40 x');
for (const t of ['', ' ', '   ', '\t']) {
  const rows = refRegion('x'.repeat(40) + t);
  console.log(`trail=${JSON.stringify(t)}  rows=${JSON.stringify(rows)}`);
}

console.log('\n--- short bodies (caret suppression)');
for (const body of ['', ' ', 'x', 'xxxxx', 'x'.repeat(23), 'x'.repeat(24), 'x'.repeat(25)]) {
  const rows = refRegion(body);
  console.log(`len=${String(body.length).padStart(2)} ${JSON.stringify(body)} rows=${JSON.stringify(rows)}`);
}

