/**
 * @typedef {object} ScriptFrame
 * @property {string} file      file name shown in the traceback and looked up
 * @property {number} line      line number shown in the traceback
 * @property {string} name      function name, e.g. "<module>"
 * @property {number} [colno]     start byte column of the failing expression
 * @property {number} [endColno]  end byte column of the failing expression
 */

/**
 * The source line plus caret line for a frame, or [] when no source is
 * available.  Follows `StackSummary.format_frame_summary`.
 */
function formatSourceLines(frame) {
  const rawLine = getLine(frame.file, frame.line);
  const stripped = stripBoth(rawLine);
  if (stripped.length === 0) return [];

  const rows = [`${SOURCE_INDENT}${stripped}`];
  if (frame.colno === undefined || frame.endColno === undefined) return rows;

  const strippedCharacters = charLength(rawLine) - charLength(stripped);
  const startOffset = byteOffsetToCharOffset(rawLine, frame.colno);
  const endOffset = byteOffsetToCharOffset(rawLine, frame.endColno);

  // The expression `base58.b58decode(args.X)` is a call, for which CPython
  // derives no sub-expression anchors, so a plain caret run is drawn.  The run
  // is suppressed only when it would span the whole visible line.
  if (endOffset - startOffset >= charLength(stripped)) return rows;

  const displayStart = displayWidth(rawLine, startOffset) + 1;
  const displayEnd = displayWidth(rawLine, endOffset) + 1;
  const indent = Math.max(0, displayStart - strippedCharacters);
  const caretCount = Math.max(0, displayEnd - displayStart);
  rows.push(`${SOURCE_INDENT}${' '.repeat(indent)}${'^'.repeat(caretCount)}`);
  return rows;
}

