/** Leading run of whitespace characters, i.e. how much `lstrip()` would remove. */
function leadingWhitespaceCount(points) {
  let n = 0;
  while (n < points.length && isPythonSpace(points[n])) n += 1;
  return n;
}

/** Drop the first `count` characters (code points, not UTF-16 units). */
function dropChars(text, count) {
  const points = toCodePoints(text);
  return points.slice(count).map((cp) => String.fromCodePoint(cp)).join('');
}

/**
 * The source line plus caret line for a frame, or [] when linecache has nothing.
 *
 * Reproduces CPython's frame rendering, which was derived here from the
 * reference program's own output:
 *   * the displayed line is the raw line with its newline removed and its
 *     indentation dedented away — trailing whitespace is kept,
 *   * the caret line is laid out against the *undedented* line and then shifted
 *     left by the same dedent, so a deep indent eats leading carets,
 *   * column offsets are byte offsets into the original source, converted to
 *     characters and then to display columns (wide characters count twice),
 *   * the caret line is dropped entirely when the marked span would cover the
 *     whole visible line.
 */
function formatSourceLines(frame) {
  const rawLine = getLine(frame.file, frame.line);
  if (rawLine.length === 0) return [];

  const withoutNewline = rawLine.endsWith('\n') ? rawLine.slice(0, -1) : rawLine;
  const indent = leadingWhitespaceCount(toCodePoints(withoutNewline));
  const displayed = dropChars(withoutNewline, indent);

  const rows = [`${SOURCE_INDENT}${displayed}`];
  if (frame.colno === undefined || frame.endColno === undefined) return rows;

  const startOffset = byteOffsetToCharOffset(rawLine, frame.colno);
  const endOffset = byteOffsetToCharOffset(rawLine, frame.endColno);
  if (endOffset - startOffset >= charLength(displayed)) return rows;

  const displayStart = displayWidth(rawLine, startOffset);
  const displayEnd = displayWidth(rawLine, endOffset);
  const caretRow = SOURCE_INDENT
    + ' '.repeat(displayStart)
    + '^'.repeat(Math.max(0, displayEnd - displayStart));
  rows.push(dropChars(caretRow, indent));
  return rows;
}

