//     `test15.py` exists relative to the cwd.  The caret run underneath is
//     positioned from the compiled column offsets, independently of what the file
//     on disk actually contains.

import { PythonError } from './errors.mjs';
import { getLine } from './linecache.mjs';
import { encodeUtf8, isPythonSpace, toCodePoints } from './unicode.mjs';
import { displayWidth } from './width.mjs';

const SOURCE_INDENT = '    ';

/** `str.strip()` over Python's whitespace set. */
function stripBoth(text) {
  const points = toCodePoints(text);
  let start = 0;
  let end = points.length;
  while (start < end && isPythonSpace(points[start])) start += 1;
  while (end > start && isPythonSpace(points[end - 1])) end -= 1;
  return points.slice(start, end).map((cp) => String.fromCodePoint(cp)).join('');
}

/** Number of code points in a string (not UTF-16 units). */
function charLength(text) {
  return toCodePoints(text).length;
}

/**
 * `traceback._byte_offset_to_character_offset`: how many characters the first
 * `offset` UTF-8 bytes of `text` decode to.  A sequence cut in half contributes
 * one character, because the replacing decoder substitutes one U+FFFD for it.
 */
function byteOffsetToCharOffset(text, offset) {
  if (offset <= 0) return 0;
  let bytes = 0;
  let chars = 0;
  for (const codePoint of toCodePoints(text)) {
    const size = encodeUtf8(String.fromCodePoint(codePoint)).length;
    if (bytes + size > offset) return chars + 1;
    bytes += size;
    chars += 1;
    if (bytes === offset) return chars;
  }
  return chars;
}

/**
 * @typedef {object} ScriptFrame
 * @property {string} file      file name shown in the traceback and looked up
 * @property {number} line      line number shown in the traceback
 * @property {string} name      function name, e.g. "<module>"
 * @property {number} [colno]     start byte column of the failing expression
 * @property {number} [endColno]  end byte column of the failing expression
 */

/** Leading run of whitespace characters, i.e. how much `lstrip()` would remove. */
function leadingWhitespaceCount(points) {
  let n = 0;
  while (n < points.length && isPythonSpace(points[n])) n += 1;
  return n;
}

/** Drop the first `count` characters (code points, not UTF-16 units). */
function dropChars(text, count) {
  const points = toCodePoints(text);
  return points.slice(count).map((cp) => String.fromCodePoint(cp)).join('');
}

