#!/usr/bin/env node
// Probe how the reference renders the traceback source row / caret row for
// various planted test15.py line-13 contents, and compare with the port.

import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const EXE = '/workspace/dataset/test15_executable';
const PORT = '/output/test15.mjs';

const NBSP = ' ';
const IDEO = '　';
const REAL = 'dec1 = base58.b58decode(args.c)  # tail tail tail';

const line13Cases = {
  'empty': '',
  'spaces-only': '     ',
  'tabs-only': '\t\t',
  'one-char': 'x',
  'len5': 'abcde',
  'len23': 'x'.repeat(23),
  'len24': 'x'.repeat(24),
  'len25': 'x'.repeat(25),
  'len31': 'x'.repeat(31),
  'len32': 'x'.repeat(32),
  'indent2-len24': `  ${'x'.repeat(24)}`,
  'indent8-len40': `        ${'x'.repeat(40)}`,
  'tab-indent': `\t${'x'.repeat(40)}`,
  'real-line': 'dec1 = base58.b58decode(args.c)  # 解码Base58字符串1',
  'cjk-prefix': '中文中文 = base58.b58decode(args.c)  # tail tail',
  'emoji-prefix': '\u{1f600}\u{1f600} = base58.b58decode(args.c)  # tail tail',
  'space-lead': `  ${REAL}`,
  'trailing-ws': `${'x'.repeat(40)}   `,
  // Indentation class: textwrap.dedent only removes spaces and tabs.
