// lib/python/traceback.mjs
//
// Renders an uncaught PythonError the way the reference program does: a CPython
// traceback followed by the frozen-app footer.
//
// Two details are reproduced from the reference:
//   * only the script frame can show a source line — the bundled library modules
//     have no source available at run time,
//   * that source line comes from `linecache`, so it appears only when a readable
//     `test15.py` exists relative to the cwd.  The caret run underneath is
//     positioned from the compiled column offsets, independently of what the file
//     on disk actually contains.

import { PythonError } from './errors.mjs';
import { getLine } from './linecache.mjs';
import { encodeUtf8, toCodePoints } from './unicode.mjs';
import { displayWidth } from './width.mjs';

const SOURCE_INDENT = '    ';

/** Number of code points in a string (not UTF-16 units). */
function charLength(text) {
  return toCodePoints(text).length;
}

/**
 * `traceback._byte_offset_to_character_offset`: how many characters the first
 * `offset` UTF-8 bytes of `text` decode to.  A sequence cut in half contributes
 * one character, because the replacing decoder substitutes one U+FFFD for it.
 */
function byteOffsetToCharOffset(text, offset) {
  if (offset <= 0) return 0;
  let bytes = 0;
  let chars = 0;
  for (const codePoint of toCodePoints(text)) {
    const size = encodeUtf8(String.fromCodePoint(codePoint)).length;
    if (bytes + size > offset) return chars + 1;
    bytes += size;
    chars += 1;
    if (bytes === offset) return chars;
  }
  return chars;
}

/**
 * @typedef {object} ScriptFrame
 * @property {string} file      file name shown in the traceback and looked up
 * @property {number} line      line number shown in the traceback
 * @property {string} name      function name, e.g. "<module>"
 * @property {number} [colno]     start byte column of the failing expression
 * @property {number} [endColno]  end byte column of the failing expression
 */

/**
 * Leading run of dedentable indentation.  CPython dedents frame source with
 * `textwrap.dedent`, whose character class is only space and tab — so an exotic
 * whitespace character such as NBSP is left in place.
 */
function leadingIndentCount(points) {
  let n = 0;
  while (n < points.length && (points[n] === 0x20 || points[n] === 0x09)) n += 1;
  return n;
}

/** Drop the first `count` characters (code points, not UTF-16 units). */
function dropChars(text, count) {
  const points = toCodePoints(text);
  return points.slice(count).map((cp) => String.fromCodePoint(cp)).join('');
}

/**
 * The source line plus caret line for a frame, or [] when linecache has nothing.
 *
 * Reproduces CPython's frame rendering, which was derived here from the
 * reference program's own output:
 *   * the displayed line is the raw line with its newline removed and its
 *     indentation dedented away — trailing whitespace is kept,
 *   * the caret line is laid out against the *undedented* line and then shifted
 *     left by the same dedent, so a deep indent eats leading carets,
 *   * column offsets are byte offsets into the original source, converted to
 *     characters and then to display columns (wide characters count twice),
 *   * the caret line is dropped entirely when the marked span would cover the
 *     whole visible line.
 */
function formatSourceLines(frame) {
  const rawLine = getLine(frame.file, frame.line);
  if (rawLine.length === 0) return [];

  const withoutNewline = rawLine.endsWith('\n') ? rawLine.slice(0, -1) : rawLine;
  const indent = leadingIndentCount(toCodePoints(withoutNewline));
  const displayed = dropChars(withoutNewline, indent);

  const rows = [`${SOURCE_INDENT}${displayed}`];
  if (frame.colno === undefined || frame.endColno === undefined) return rows;

  const startOffset = byteOffsetToCharOffset(rawLine, frame.colno);
  const endOffset = byteOffsetToCharOffset(rawLine, frame.endColno);
  if (endOffset - startOffset >= charLength(displayed)) return rows;

  const displayStart = displayWidth(rawLine, startOffset);
  const displayEnd = displayWidth(rawLine, endOffset);
  const caretRow = SOURCE_INDENT
    + ' '.repeat(displayStart)
    + '^'.repeat(Math.max(0, displayEnd - displayStart));
  rows.push(dropChars(caretRow, indent));
  return rows;
}

/**
 * @param {PythonError} error
 * @param {ScriptFrame} scriptFrame
 * @returns {string} the traceback, newline-terminated
 */
export function formatTraceback(error, scriptFrame) {
  const lines = ['Traceback (most recent call last):'];
  lines.push(
    `  File "${scriptFrame.file}", line ${scriptFrame.line}, in ${scriptFrame.name}`,
  );
  lines.push(...formatSourceLines(scriptFrame));

  for (const frame of error instanceof PythonError ? error.pyFrames : []) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
  }

  lines.push(`${error.typeName}: ${error.text}`);
  return `${lines.join('\n')}\n`;
}

/**
 * The line the PyInstaller bootloader prints after an unhandled exception.  Its
 * numeric field is the process id, so it differs between runs of the reference
 * program too.
 */
export function formatFrozenFooter(scriptName, pid) {
  return `[PYI-${pid}:ERROR] Failed to execute script '${scriptName}' `
    + 'due to unhandled exception!\n';
}

/** Write the traceback plus footer to stderr. */
export function reportFatal(error, scriptFrame, scriptName, pid) {
  process.stderr.write(formatTraceback(error, scriptFrame));
  process.stderr.write(formatFrozenFooter(scriptName, pid));
}

